-- Duplicating a brand: the plan from apps/web/src/lib/duplicate.ts (generated by
-- scripts/duplicate-ops.ts) applies through the real save function, and the copy
-- only references its own rows.
\set ON_ERROR_STOP on
\set QUIET on

create temp table dup_input (doc jsonb);
insert into dup_input values (:'duplicate_ops'::jsonb);
grant select on dup_input to authenticated;

insert into auth.users (id, email) values ('ad000000-0000-4000-8000-000000000009', 'dee@example.com');
set role authenticated;
select set_config('request.jwt.claim.sub', 'ad000000-0000-4000-8000-000000000009', false);

insert into public.brands (id, workspace_id, name, slug, created_by)
select v.id, w.id, v.name, v.slug, auth.uid()
from public.workspaces w,
  (values ('bd000000-0000-4000-8000-000000000001'::uuid, 'Original', 'dup-original'),
          ('bd000000-0000-4000-8000-000000000002'::uuid, 'Original (copy)', 'dup-copy')) as v(id, name, slug);

select public.apply_draft_ops('bd000000-0000-4000-8000-000000000001', 0, (select doc -> 'seed' from dup_input)) > 0 as ok \gset
select tests.ok(:'ok'::boolean, 'the source brand is seeded');

select public.apply_draft_ops('bd000000-0000-4000-8000-000000000002', 0, (select doc -> 'copy' from dup_input)) > 0 as ok \gset
select tests.ok(:'ok'::boolean, 'the duplicate applies in one save');

create temp view dup_counts as
select b.id as brand_id,
  (select count(*) from public.sections where brand_id = b.id) as sections,
  (select count(*) from public.sections where brand_id = b.id and hidden) as hidden_sections,
  (select count(*) from public.blocks where brand_id = b.id) as blocks,
  (select count(*) from public.blocks where brand_id = b.id and parent_block_id is not null) as nested_blocks,
  (select count(*) from public.color_tokens where brand_id = b.id) as colors,
  (select count(*) from public.type_families where brand_id = b.id) as families,
  (select count(*) from public.type_styles where brand_id = b.id) as styles,
  (select count(*) from public.assets where brand_id = b.id) as assets,
  (select count(*) from public.font_files where brand_id = b.id) as font_files,
  (select count(*) from public.strategy_fields where brand_id = b.id) as strategy
from public.brands b where b.id in ('bd000000-0000-4000-8000-000000000001', 'bd000000-0000-4000-8000-000000000002');

select tests.ok(
  (select count(distinct (sections, hidden_sections, blocks, nested_blocks, colors, families, styles, assets, font_files, strategy)) = 1 from dup_counts),
  'the copy has the same sections, blocks, colours, type, assets and strategy as the original');
select tests.ok((select sections = 3 and hidden_sections = 1 and nested_blocks = 1 and font_files = 1 from dup_counts limit 1),
  'nesting, hidden sections and font files are kept');

select tests.ok(not exists (
  select 1 from public.blocks b, jsonb_array_elements_text(b.props -> 'tokenIds') t
  where b.brand_id = 'bd000000-0000-4000-8000-000000000002'
    and not exists (select 1 from public.color_tokens c where c.id = t::uuid and c.brand_id = b.brand_id)
), 'palette colours in the copy all belong to the copy');

select tests.ok(not exists (
  select 1 from public.blocks b
  where b.brand_id = 'bd000000-0000-4000-8000-000000000002' and b.type = 'image'
    and (not exists (select 1 from public.assets a where a.id = (b.props ->> 'assetId')::uuid and a.brand_id = b.brand_id)
      or not exists (select 1 from public.color_tokens c where c.id = (b.props ->> 'background')::uuid and c.brand_id = b.brand_id))
), 'image asset and background in the copy belong to the copy');

select tests.ok(not exists (
  select 1 from public.blocks b, jsonb_array_elements_text(b.props -> 'styleIds') t
  where b.brand_id = 'bd000000-0000-4000-8000-000000000002'
    and not exists (select 1 from public.type_styles s where s.id = t::uuid and s.brand_id = b.brand_id)
), 'type specimen styles in the copy belong to the copy');

select tests.ok(not exists (
  select 1 from public.assets where brand_id = 'bd000000-0000-4000-8000-000000000002'
    and split_part(storage_path, '/', 1) <> 'bd000000-0000-4000-8000-000000000002'
), 'copied files live in the copy''s storage folder');

update public.color_tokens set hex = '#000000' where brand_id = 'bd000000-0000-4000-8000-000000000002' and name = 'Ember';
select tests.ok((select hex from public.color_tokens where brand_id = 'bd000000-0000-4000-8000-000000000001' and name = 'Ember') = '#D2491E',
  'editing the copy leaves the original untouched');

select tests.ok((select status from public.brands where id = 'bd000000-0000-4000-8000-000000000002') = 'draft', 'the copy starts as an unpublished draft');
reset role;

\echo 'Duplicate tests passed.'
